#[cfg(test)]
mod tests {
    use super::*;

    fn temp_path(name: &str) -> std::path::PathBuf {
        std::env::temp_dir().join(format!("mia-test-{}-{name}", std::process::id()))
    }

    fn ctx(handle: &crate::agent_loop::AgentHandle) -> ToolContext<'_> {
        ToolContext {
            handle,
            session_id: "test",
        }
    }

    #[tokio::test]
    async fn writes_file_and_creates_parents() {
        let (_rx, handle) = crate::agent_loop::AgentHandle::new();
        let dir = temp_path("write");
        let path = dir.join("sub/dir/out.txt");
        let (status, payload) = FSWriteFile
            .execute(
                &ctx(&handle),
                json!({ "path": path.to_string_lossy(), "content": "hello world" }),
            )
            .await;
        assert_eq!(status, ToolStatus::Success);
        assert_eq!(payload["size"], 11);
        assert_eq!(fs::read_to_string(&path).unwrap(), "hello world");
        fs::remove_dir_all(&dir).ok();
    }

    #[tokio::test]
    async fn missing_content_is_error() {
        let (_rx, handle) = crate::agent_loop::AgentHandle::new();
        let (status, payload) = FSWriteFile
            .execute(&ctx(&handle), json!({ "path": "/tmp/nonexistent.md" }))
            .await;
        assert!(matches!(status, ToolStatus::Error(_)));
        assert_eq!(payload["message"], "content argument not found");
    }
}
